(@irq1s1, 'Valid Passport (6+ Months Validity)', NULL, 'original', 1, 0, 1, 1),
(@irq1s1, 'Approved eVisa or Embassy Visa', NULL, 'copy', 1, 0, 1, 2),
(@irq1s1, 'Hotel Booking Confirmation or Invitation Letter', NULL, 'copy', 1, 0, 1, 3);

